struct PaymentMapper {                       // abstract mapping behaviour
  virtual ~PaymentMapper() = default;
  virtual PaymentPtr load(const Row& r) const = 0;
  virtual void save(const Payment& p, Row& r) const = 0;
};
struct CardPaymentMapper : PaymentMapper {
  PaymentPtr load(const Row& r) const override {
    auto p = std::make_shared<CardPayment>();
    base_.loadInto(r, *p);                                // superclass slice first
    p->cardNumber = r.get<std::string>("card_number");     // then own columns
    return p;
  }
};

